INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63942403', 63942403, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pengelolaan, Administrasi dan Pemuktahiran Data Kepegawaian', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan pengelolaan, administrasi, dan pemutakhiran data kepegawaian dilaksanakan untuk menjamin ketersediaan data pegawai yang akurat, mutakhir, dan dapat dipertanggungjawabkan sebagai dasar pengambilan keputusan manajerial dan pelaksanaan administrasi kepegawaian. Ruang lingkup kegiatan meliputi: 1. Pengelolaan administrasi kepegawaian secara tertib dan sistematis. 2. Pemutakhiran data pegawai sesuai perubahan status, jabatan, dan riwayat kepegawaian. 3. Penginputan dan verifikasi data pada sistem informasi kepegawaian. 4. Penyusunan dan pemeliharaan arsip data kepegawaian. 5. Dukungan administrasi dalam pelayanan kepegawaian pegawai. Kegiatan ini bertujuan untuk mendukung tertib administrasi kepegawaian, meningkatkan kualitas layanan kepegawaian, serta mendukung pelaksanaan tugas dan fungsi satuan kerja secara efektif dan efisien.', '1. Pengelolaan Data Kepegawaian o Pendataan dan pembaruan data identitas dan riwayat pegawai. o Penataan dan pemeliharaan basis data kepegawaian. 2. Administrasi Kepegawaian o Penyusunan dan pengelolaan dokumen kepegawaian. o Pelayanan administrasi kepegawaian sesuai ketentuan. 3. Pemutakhiran dan Verifikasi Data o Pembaruan data secara berkala dan berkelanjutan. o Verifikasi kebenaran dan kelengkapan data. 4. Sistem dan Keamanan Data o Pengelolaan data melalui sistem informasi kepegawaian yang berlaku. o Menjaga kerahasiaan dan keamanan data pegawai. 5. Hasil yang Diharapkan o Tersedianya data kepegawaian yang akurat dan mutakhir. o Tertib administrasi dan meningkatnya kualitas layanan kepegawaian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1270231);
