INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63942578', 63942578, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penyusunan Renstra 2025-2029', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan penyusunan Renstra 2025–2029 dilaksanakan untuk menghasilkan dokumen perencanaan strategis yang menjadi pedoman pelaksanaan tugas dan fungsi satuan kerja dalam jangka menengah lima tahunan, selaras dengan kebijakan nasional/daerah dan ketentuan peraturan perundang-undangan. Ruang lingkup kegiatan meliputi: 1. Pengumpulan dan analisis data serta evaluasi kinerja periode sebelumnya. 2. Penyusunan visi, misi, tujuan, sasaran, dan arah kebijakan. 3. Penetapan indikator kinerja dan target capaian. 4. Penyelarasan Renstra dengan dokumen perencanaan yang lebih tinggi. 5. Finalisasi dan penetapan dokumen Renstra 2025–2029.', '1. Analisis Awal o Analisis kondisi internal dan eksternal satuan kerja. o Evaluasi capaian kinerja periode sebelumnya. 2. Perumusan Dokumen o Penyusunan visi, misi, tujuan, dan sasaran strategis. o Penetapan program, kegiatan, dan indikator kinerja. o Penyusunan kerangka pendanaan indikatif. 3. Sinkronisasi dan Koordinasi o Penyelarasan dengan RPJMN/RPJMD dan kebijakan terkait. o Koordinasi dengan unit kerja dan pemangku kepentingan. 4. Finalisasi Dokumen o Penyempurnaan dokumen berdasarkan hasil pembahasan. o Penetapan dan dokumentasi Renstra 2025–2029. 5. Hasil yang Diharapkan o Tersusunnya Dokumen Renstra 2025–2029 yang komprehensif dan berkualitas. o Tersedianya pedoman strategis pelaksanaan program dan kegiatan lima tahunan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1272494);
