INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63943100', 63943100, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Penyusunan TRPNBP dilaksanakan untuk menetapkan target, rencana, dan proyeksi Penerimaan Negara Bukan Pajak (PNBP) secara terukur, realistis, dan akuntabel sebagai dasar perencanaan dan penganggaran satuan kerja sesuai dengan ketentuan peraturan perundang-undangan. Ruang lingkup kegiatan meliputi: 1. Pengumpulan dan analisis data historis realisasi PNBP. 2. Penyusunan target PNBP berdasarkan potensi dan kebijakan yang berlaku. 3. Penyusunan rencana dan proyeksi PNBP tahun anggaran berjalan. 4. Koordinasi dan sinkronisasi dengan unit terkait dan instansi pembina. 5. Penyampaian dokumen TRPNBP sesuai jadwal yang ditetapkan.', '1. Pengumpulan dan Analisis Data o Pengumpulan data realisasi PNBP tahun-tahun sebelumnya. o Analisis potensi dan tren PNBP berdasarkan jenis layanan/kegiatan. 2. Penyusunan Target PNBP o Penetapan target PNBP per jenis penerimaan. o Penyesuaian target dengan kebijakan dan kapasitas satuan kerja. 3. Penyusunan Rencana dan Proyeksi o Penyusunan rencana penerimaan PNBP secara periodik. o Proyeksi PNBP berdasarkan asumsi dan potensi yang terukur. 4. Koordinasi dan Sinkronisasi o Koordinasi dengan unit teknis pengelola PNBP. o Sinkronisasi dengan instansi pembina dan sistem perencanaan anggaran. 5. Penyusunan Dokumen TRPNBP o Penyusunan dokumen TRPNBP yang lengkap dan sistematis. o Penyesuaian dokumen berdasarkan hasil pembahasan dan evaluasi. 6. Pelaporan dan Dokumentasi o Penyampaian dokumen TRPNBP sesuai ketentuan. o Pengarsipan data dan dokumen pendukung TRPNBP. 7. Standar Pelaksanaan o Mengacu pada peraturan perundang-undangan di bidang PNBP. o Dilaksanakan secara akurat, transparan, dan akuntabel. 8. Hasil yang Diharapkan o Tersusunnya dokumen TRPNBP yang valid dan dapat dipertanggungjawabkan. o Mendukung optimalisasi perencanaan dan pengelolaan PNBP satuan kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1273357);
