INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63963564', 63963564, 'analyze_legacy', 'Kejaksaan Republik Indonesia', 'central', 'KEJAKSAAN NEGERI BUOL', 'Pengadaan Outsourcing Kejaksaan Negeri Buol Tahun 2026', 'Barang', 'E-Purchasing', 'Sulawesi Tengah, Buol (Kab.)', 1108244000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Outsourcing Kejaksaan Negeri Buol Tahun 2026 Berjumlah 17 org dengan rincian sebagai berikut : Pengawas 1 org Pramubakti 5 org Tenaga Kebersihan 3 org Pengemudi 1 org Petugas PTSP 1 org Satpam 6 org', 'Umum: WNI, usia minimal 18 tahun dan maksimal 50 tahun (kecuali ditentukan lain), sehat jasmani dan rohani, serta berkelakuan baik. Khusus Pengawas : Pengalaman minimal 1 tahun sebagai koordinator lapangan atau supervisor outsourcing. Memiliki jiwa kepemimpinan yang tegas namun komunikatif. Wajib menguasai MS Office (Word & Excel) untuk penyusunan laporan dan pengiriman email. Pendidikan minimal D3/S1 (lebih diutamakan untuk memudahkan koordinasi administratif). Khusus Satpam: Wajib memiliki minimal sertifikat Gada Pratama dan KTA yang masih aktif. Khusus PTSP: Berpenampilan menarik (good looking), komunikatif, dan menguasai penggunaan komputer dasar. Khusus Driver : Bebas narkoba dan miras (dibuktikan dengan surat keterangan). Tidak memiliki catatan kriminal. Memahami rute jalan di wilayah Sulawesi Tengah dan sekitarnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1273495);
