INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63943233', 63943233, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 1000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Penyusunan Revisi DIPA/POK dilaksanakan untuk menyesuaikan pelaksanaan anggaran dengan kebutuhan riil, kebijakan pemerintah, serta dinamika pelaksanaan program dan kegiatan pada satuan kerja agar tetap efektif, efisien, dan sesuai ketentuan peraturan perundang-undangan. Ruang lingkup kegiatan meliputi: 1. Identifikasi kebutuhan revisi anggaran dan kegiatan. 2. Penyusunan dokumen revisi DIPA dan/atau POK. 3. Koordinasi dan konsultasi dengan unit terkait dan instansi pembina. 4. Pengajuan, pemrosesan, dan penetapan revisi sesuai mekanisme yang berlaku. 5. Penyesuaian dokumen pelaksanaan anggaran pasca revisi.', '1. Identifikasi dan Analisis Kebutuhan Revisi o Analisis deviasi rencana dan realisasi anggaran. o Identifikasi perubahan kegiatan, output, akun, atau pagu. 2. Penyusunan Dokumen Revisi o Penyusunan usulan revisi DIPA dan/atau POK. o Penyesuaian struktur anggaran, jadwal, dan target output kegiatan. 3. Penginputan dan Pemrosesan Revisi o Penginputan data revisi pada aplikasi perencanaan dan penganggaran yang berlaku. o Verifikasi kelengkapan dan kesesuaian data revisi. 4. Koordinasi dan Konsultasi o Koordinasi dengan unit internal, KPPN, dan instansi pembina terkait. o Konsultasi teknis revisi anggaran sesuai ketentuan. 5. Penetapan dan Penyesuaian Dokumen o Tindak lanjut persetujuan revisi DIPA/POK. o Penyesuaian dokumen pelaksanaan kegiatan dan anggaran. 6. Dokumentasi dan Pelaporan o Pengarsipan dokumen revisi DIPA/POK. o Pelaporan pelaksanaan revisi anggaran. 7. Standar Pelaksanaan o Mengacu pada peraturan perundang-undangan di bidang pengelolaan keuangan negara. o Dilaksanakan secara tertib, transparan, dan akuntabel. 8. Hasil yang Diharapkan o Tersusunnya revisi DIPA/POK yang sah dan sesuai ketentuan. o Mendukung kelancaran dan optimalisasi pelaksanaan anggaran satuan kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1273650);
