INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63942841', 63942841, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Penyusunan RKA-K/L dilaksanakan untuk menyusun dokumen perencanaan dan penganggaran yang terintegrasi, sistematis, dan akuntabel, sebagai dasar pelaksanaan program dan kegiatan Kementerian/Lembaga sesuai dengan arah kebijakan nasional dan ketentuan peraturan perundang-undangan. Ruang lingkup kegiatan meliputi: 1. Penyusunan rencana kerja dan anggaran berdasarkan pagu indikatif/definitif. 2. Penyelarasan program, kegiatan, output, dan anggaran. 3. Penginputan dan pengelolaan data RKA-K/L pada sistem perencanaan dan penganggaran. 4. Koordinasi, pembahasan, dan penyesuaian RKA-K/L dengan unit terkait. 5. Finalisasi dan penyampaian dokumen RKA-K/L sesuai ketentuan.', '1. Persiapan Penyusunan o Pengumpulan data perencanaan, kebijakan, dan pagu anggaran. o Analisis kebutuhan anggaran berdasarkan prioritas program dan kegiatan. 2. Penyusunan Dokumen RKA-K/L o Penyusunan struktur program, kegiatan, output, dan komponen biaya. o Penetapan indikator kinerja dan target output kegiatan. 3. Penginputan dan Verifikasi Data o Penginputan data RKA-K/L pada aplikasi perencanaan dan penganggaran yang berlaku. o Verifikasi kesesuaian data dengan ketentuan dan pagu anggaran. 4. Koordinasi dan Pembahasan o Koordinasi dengan unit internal dan instansi pembina terkait. o Pembahasan dan penyesuaian RKA-K/L berdasarkan hasil evaluasi. 5. Finalisasi dan Penyampaian o Finalisasi dokumen RKA-K/L. o Penyampaian RKA-K/L sesuai jadwal yang ditetapkan. 6. Dokumentasi dan Pelaporan o Pengarsipan dokumen RKA-K/L dan data pendukung. o Pelaporan proses dan hasil penyusunan RKA-K/L. 7. Standar Pelaksanaan o Mengacu pada peraturan perundang-undangan di bidang perencanaan dan penganggaran. o Dilaksanakan secara tertib, akuntabel, dan tepat waktu. 8. Hasil yang Diharapkan o Tersusunnya RKA-K/L yang valid, konsisten, dan dapat dipertanggungjawabkan. o Mendukung kelancaran pelaksanaan anggaran Kementerian/Lembaga.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1274327);
