INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63944232', 63944232, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan penyusunan Laporan Keuangan (LK) tingkat UAKPA/Satuan Kerja dilaksanakan untuk menghasilkan laporan keuangan yang akurat, andal, tepat waktu, dan sesuai dengan Standar Akuntansi Pemerintahan (SAP) sebagai bentuk pertanggungjawaban pelaksanaan anggaran dan pengelolaan keuangan negara/daerah. Ruang lingkup kegiatan meliputi: 1. Pengumpulan dan pengolahan data transaksi keuangan. 2. Penyusunan laporan keuangan tingkat UAKPA/Satuan Kerja. 3. Rekonsiliasi internal dan eksternal sesuai ketentuan. 4. Penyampaian laporan keuangan kepada unit terkait.', '1. Penyusunan Laporan Keuangan o Penyusunan Laporan Realisasi Anggaran (LRA). o Penyusunan Neraca. o Penyusunan Laporan Operasional (LO). o Penyusunan Laporan Perubahan Ekuitas (LPE). o Penyusunan Catatan atas Laporan Keuangan (CaLK). 2. Pengelolaan dan Verifikasi Data o Penginputan dan pengolahan data pada aplikasi keuangan yang berlaku. o Verifikasi kelengkapan dan kebenaran data transaksi. 3. Rekonsiliasi o Rekonsiliasi internal antar unit terkait. o Rekonsiliasi eksternal dengan instansi pembina/mitra terkait. 4. Pelaporan o Penyampaian laporan keuangan sesuai jadwal yang ditetapkan. o Penyediaan data dan dokumen pendukung pemeriksaan. 5. Standar Pelaksanaan o Mengacu pada SAP dan peraturan perundang-undangan di bidang keuangan negara/daerah. o Mengutamakan prinsip akuntabilitas, transparansi, dan ketepatan waktu. 6. Hasil yang Diharapkan o Tersusunnya LK UAKPA/Satuan Kerja yang lengkap dan dapat dipertanggungjawabkan. o Mendukung tercapainya opini pemeriksaan yang baik.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1276585);
