INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63944046', 63944046, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 2000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Pembangunan Zona Integritas (ZI) dalam rangka Reformasi Birokrasi dilaksanakan untuk mewujudkan birokrasi yang bersih, akuntabel, transparan, dan berkinerja tinggi, serta meningkatkan kualitas pelayanan publik melalui penerapan prinsip integritas dan tata kelola pemerintahan yang baik. Ruang lingkup kegiatan meliputi: 1. Penyusunan dan pelaksanaan rencana kerja Pembangunan Zona Integritas. 2. Penguatan komitmen pimpinan dan seluruh pegawai. 3. Implementasi Reformasi Birokrasi pada enam area perubahan ZI. 4. Pemantauan, evaluasi, dan pelaporan pelaksanaan ZI. 5. Koordinasi, asistensi, dan penyiapan penilaian ZI. Kegiatan ini bertujuan untuk mendorong satuan kerja memenuhi kriteria Wilayah Bebas dari Korupsi (WBK) dan/atau Wilayah Birokrasi Bersih dan Melayani (WBBM).', '1. Manajemen Perubahan o Pembentukan tim kerja ZI dan penyusunan rencana aksi. o Sosialisasi dan internalisasi budaya kerja berintegritas. 2. Penataan Tatalaksana o Penyusunan dan penyempurnaan SOP. o Penerapan sistem kerja berbasis proses dan digitalisasi layanan. 3. Penataan Sistem Manajemen SDM o Penerapan manajemen kinerja dan disiplin pegawai. o Pengelolaan SDM berbasis kompetensi dan kinerja. 4. Penguatan Akuntabilitas Kinerja o Penyelarasan perencanaan, pengukuran, dan pelaporan kinerja. o Pemantauan capaian kinerja dan tindak lanjut hasil evaluasi. 5. Penguatan Pengawasan o Penerapan pengendalian internal dan manajemen risiko. o Pengelolaan pengaduan masyarakat, gratifikasi, dan benturan kepentingan. 6. Peningkatan Kualitas Pelayanan Publik o Penyusunan dan penerapan standar pelayanan. o Pelaksanaan survei kepuasan masyarakat dan tindak lanjut perbaikan layanan. 7. Standar Pelaksanaan o Mengacu pada pedoman Reformasi Birokrasi dan Pembangunan ZI. o Dilaksanakan secara konsisten, terukur, dan berkelanjutan. 8. Hasil yang Diharapkan o Terbangunnya budaya kerja berintegritas. o Meningkatnya kualitas pelayanan publik. o Tercapainya predikat WBK/WBBM.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1278038);
